"""
    Wrapper Function to wrap the existing worker_init_fn and seed numpy before
    calling the actual ``worker_init_fn``

    Parameters
    ----------
    worker_id : int
        the number of the worker
    seed : int32
        the base seed in a range of [0, 2**32 - (1 + ``num_workers``)].
        The range ensures, that the whole seed, which consists of the base
        seed and the ``worker_id``, can still be represented as a unit32,
        as it needs to be for numpy seeding
    worker_init_fn : callable, optional
        will be called with the ``worker_id`` after seeding numpy if it is not
        ``None``
    """
def _seed_npy_before_worker_init(
    worker_id: Any, seed: Any, worker_init_fn: Any = None
) -> object {
    try {
        import numpy as np;
        np.random.seed((seed + worker_id));
    } except ImportError {
        ;
    }
    if (worker_init_fn is not None) {
        return worker_init_fn(worker_id);
    }
}

"""
    Factor the total count in to the difference of the new value.
    E.g. for a value of 100ms with 50 measurements, a new measure of 150ms would add 1 ms to the total
    """
def calc_new_value(old_measure: Any, new_measure: Any, count: Any) -> object {
    return (
        (old_measure + (old_measure + ((new_measure - old_measure) * (1.0 / count))))
        / 2.0
    );
}
